window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-727ac805c5002da2"]={"versions": [{"id": "FIG-727ac805c5002da2", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram / Action Flow) zur Spezifikation eines atomaren algorithmischen Einzelschritts.</li>\n<li><strong>Kontext:</strong> AUTOSAR Foundation / Classic Platform – Spezifikation des E2E-Protokolls (<code>AUTOSAR_FO_PRS_E2EProtocol</code>, Release R24-11).</li>\n<li><strong>Funktionale Einordnung:</strong> Detaillierung des Teilschritts „Write Counter“ innerhalb der Schutzfunktion <code>E2E_P76Protect()</code> für das E2E-Profil 76 (Profile 76, u. a. abgeleitet aus bzw. kompatibel zu sicherheitsgerichteten Nutzfahrzeug-Standards wie SAE J1939-76). Dient der Absicherung von Nutzdaten gegen Nachrichtenverlust, Wiederholung und Vertauschung vor der CRC-Berechnung und PDU-Übertragung.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktionskontext:</strong> Sub-Aktivität von <code>E2E_P76Protect()</code> (symbolisiert durch das aufrufende Funktionssymbol oben links).</li>\n<li><strong>Datenstrukturen & Parameter:</strong></li>\n<li><code>Data</code> (<code>uint8*</code>): Zu schützender serialisierter PDU-Byte-Buffer.</li>\n<li><code>State</code> (<code>E2E_P76ProtectStateType*</code>): Zustandsstruktur des Senders mit dem sequenziellen Alive-Counter <code>State-&gt;Counter</code>.</li>\n<li>Byte 0 von <code>Data</code>: Ziel-Header-Byte zur Aufnahme des Zählers.</li>\n<li><strong>UML-Elemente & Entitäten:</strong></li>\n<li><code>UML::InitialNode</code>: Einstiegspunkt der Sequenz.</li>\n<li><code>UML::OpaqueAction</code> (1): <em>„Copy parameter State->Counter to bytstring Data.“</em> (Übertrag des Zustandszählers in das Daten-Array).</li>\n<li><code>UML::OpaqueAction</code> (2): <em>„Set upper 3 bits of byte 0 in data to 0.“</em> (Bitmaskierung des Zielbytes).</li>\n<li><code>UML::Comment</code> (an Action 2 annotiert): <em>„Limit counter to values 0 to 0x1F“</em> (Spezifiziert die Beschränkung auf einen 5-Bit-Wertebereich <code>[0 .. 31]</code>).</li>\n<li><code>UML::ActivityFinalNode</code>: Regulärer Abschluss der Zähler-Schreiboperation.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Aufrufkontext:</strong> Rein synchroner, deterministischer In-Memory-Ablauf ($O(1)$) innerhalb der Ausführung von <code>E2E_P76Protect()</code>, nachdem grundlegende Parameterprüfungen erfolgreich waren und bevor die CRC über das Gesamtdatenfeld gebildet wird.</li>\n<li><strong>Chronologie:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Start:</strong> Aktivierung über den Initialknoten bei Eintritt in die Phase „Write Counter“.</li>\n<li><strong>Schritt 1 (Zähler kopieren):</strong> Zuweisung des aktuellen Zählerstands aus <code>State-&gt;Counter</code> in Byte 0 von <code>Data</code> (bzw. an das profilkonforme Header-Offset).</li>\n<li><strong>Schritt 2 (Bitmaskierung):</strong> Nullsetzen der höchstwertigen 3 Bits (Bits 7..5) von Byte 0 (<code>Data[0] &amp;= 0x1F</code>). Der effektive Zähler belegt ausschließlich die niederwertigen 5 Bits (Bits 4..0).</li>\n<li><strong>Abschluss:</strong> Verzweigung auf den Finalknoten; Fortführung des Protect-Ablaufs (Übergang zur Berechnung und zum Schreiben der CRC).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Abbrüche / Fehlerpfade:</strong> Keine Verzweigungen oder Fehlerbehandlungen innerhalb dieses Teilablaufs; ungültige Zeiger (<code>NULL_PTR</code>) werden bereits vorab durch den Eingangs-Check von <code>E2E_P76Protect</code> abgefangen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Anforderungen:</strong> Setzt u. a. <code>PRS_E2E_01210</code>, <code>PRS_E2E_01424</code>, <code>PRS_E2E_01427</code>, <code>PRS_E2E_01428</code> und <code>PRS_E2E_01434</code> (abgeleitet aus <code>RS_E2E_08539</code>) um.</li>\n<li><strong>C-Implementierungsäquivalent:</strong></li>\n</ul>\n<p class=\"fig-p\">```c</p>\n<p class=\"fig-p\">Data[0] = (uint8)(State->Counter & 0x1Fu);</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\"><em>(Alternativ: Kopieren und anschließende Maskierung <code>Data[0] = State-&gt;Counter; Data[0] &amp;= 0x1Fu;</code>)</em>.</p>\n<ul class=\"fig-list\">\n<li><strong>Stack- & Integrationsrelevanz:</strong></li>\n<li><strong>Bit-Layout:</strong> Das oberste Nibble von Byte 0 enthält in den Bits 7..5 feste Nullen; Bit 4 gehört bereits zum Counter (Wertebereich <code>0x00</code> bis <code>0x1F</code>).</li>\n<li><strong>Empfänger-Validierung (<code>E2E_P76Check</code>):</strong> Werden die oberen 3 Bits auf Senderseite nicht deterministisch genullt, schlägt die sender- und empfängerseitige CRC-Berechnung fehl, bzw. der Check-Schritt verwirft die PDU wegen inkonsistentem Header-Format.</li>\n<li><strong>Reihenfolgeabhängigkeit:</strong> Das Schreiben und Maskieren des Counters muss zwingend <strong>vor</strong> dem Aufruf der CRC-Berechnungsroutine erfolgen, da Byte 0 Bestandteil des CRC-berechneten PDU-Bereichs ist.</li>\n</ul>"}, {"id": "FIG-9f955fed7a787bc3", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram / Action Flow) zur Spezifikation eines atomaren algorithmischen Einzelschritts.</li>\n<li><strong>Kontext:</strong> AUTOSAR Foundation / Classic Platform – Spezifikation des E2E-Protokolls (<code>AUTOSAR_FO_PRS_E2EProtocol</code>, Release R24-11).</li>\n<li><strong>Funktionale Einordnung:</strong> Detaillierung des Teilschritts „Write Counter“ innerhalb der Schutzfunktion <code>E2E_P76Protect()</code> für das E2E-Profil 76 (Profile 76, u. a. abgeleitet aus bzw. kompatibel zu sicherheitsgerichteten Nutzfahrzeug-Standards wie SAE J1939-76). Dient der Absicherung von Nutzdaten gegen Nachrichtenverlust, Wiederholung und Vertauschung vor der CRC-Berechnung und PDU-Übertragung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktionskontext:</strong> Sub-Aktivität von <code>E2E_P76Protect()</code> (symbolisiert durch das aufrufende Funktionssymbol oben links).</li>\n<li><strong>Datenstrukturen & Parameter:</strong></li>\n<li><code>Data</code> (<code>uint8*</code>): Zu schützender serialisierter PDU-Byte-Buffer.</li>\n<li><code>State</code> (<code>E2E_P76ProtectStateType*</code>): Zustandsstruktur des Senders mit dem sequenziellen Alive-Counter <code>State-&gt;Counter</code>.</li>\n<li>Byte 0 von <code>Data</code>: Ziel-Header-Byte zur Aufnahme des Zählers.</li>\n<li><strong>UML-Elemente & Entitäten:</strong></li>\n<li><code>UML::InitialNode</code>: Einstiegspunkt der Sequenz.</li>\n<li><code>UML::OpaqueAction</code> (1): <em>„Copy parameter State->Counter to bytstring Data.“</em> (Übertrag des Zustandszählers in das Daten-Array).</li>\n<li><code>UML::OpaqueAction</code> (2): <em>„Set upper 3 bits of byte 0 in data to 0.“</em> (Bitmaskierung des Zielbytes).</li>\n<li><code>UML::Comment</code> (an Action 2 annotiert): <em>„Limit counter to values 0 to 0x1F“</em> (Spezifiziert die Beschränkung auf einen 5-Bit-Wertebereich <code>[0 .. 31]</code>).</li>\n<li><code>UML::ActivityFinalNode</code>: Regulärer Abschluss der Zähler-Schreiboperation.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Aufrufkontext:</strong> Rein synchroner, deterministischer In-Memory-Ablauf ($O(1)$) innerhalb der Ausführung von <code>E2E_P76Protect()</code>, nachdem grundlegende Parameterprüfungen erfolgreich waren und bevor die CRC über das Gesamtdatenfeld gebildet wird.</li>\n<li><strong>Chronologie:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Start:</strong> Aktivierung über den Initialknoten bei Eintritt in die Phase „Write Counter“.</li>\n<li><strong>Schritt 1 (Zähler kopieren):</strong> Zuweisung des aktuellen Zählerstands aus <code>State-&gt;Counter</code> in Byte 0 von <code>Data</code> (bzw. an das profilkonforme Header-Offset).</li>\n<li><strong>Schritt 2 (Bitmaskierung):</strong> Nullsetzen der höchstwertigen 3 Bits (Bits 7..5) von Byte 0 (<code>Data[0] &amp;= 0x1F</code>). Der effektive Zähler belegt ausschließlich die niederwertigen 5 Bits (Bits 4..0).</li>\n<li><strong>Abschluss:</strong> Verzweigung auf den Finalknoten; Fortführung des Protect-Ablaufs (Übergang zur Berechnung und zum Schreiben der CRC).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Abbrüche / Fehlerpfade:</strong> Keine Verzweigungen oder Fehlerbehandlungen innerhalb dieses Teilablaufs; ungültige Zeiger (<code>NULL_PTR</code>) werden bereits vorab durch den Eingangs-Check von <code>E2E_P76Protect</code> abgefangen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Anforderungen:</strong> Setzt u. a. <code>PRS_E2E_01210</code>, <code>PRS_E2E_01424</code>, <code>PRS_E2E_01427</code>, <code>PRS_E2E_01428</code> und <code>PRS_E2E_01434</code> (abgeleitet aus <code>RS_E2E_08539</code>) um.</li>\n<li><strong>C-Implementierungsäquivalent:</strong></li>\n</ul>\n<p class=\"fig-p\">```c</p>\n<p class=\"fig-p\">Data[0] = (uint8)(State->Counter & 0x1Fu);</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\"><em>(Alternativ: Kopieren und anschließende Maskierung <code>Data[0] = State-&gt;Counter; Data[0] &amp;= 0x1Fu;</code>)</em>.</p>\n<ul class=\"fig-list\">\n<li><strong>Stack- & Integrationsrelevanz:</strong></li>\n<li><strong>Bit-Layout:</strong> Das oberste Nibble von Byte 0 enthält in den Bits 7..5 feste Nullen; Bit 4 gehört bereits zum Counter (Wertebereich <code>0x00</code> bis <code>0x1F</code>).</li>\n<li><strong>Empfänger-Validierung (<code>E2E_P76Check</code>):</strong> Werden die oberen 3 Bits auf Senderseite nicht deterministisch genullt, schlägt die sender- und empfängerseitige CRC-Berechnung fehl, bzw. der Check-Schritt verwirft die PDU wegen inkonsistentem Header-Format.</li>\n<li><strong>Reihenfolgeabhängigkeit:</strong> Das Schreiben und Maskieren des Counters muss zwingend <strong>vor</strong> dem Aufruf der CRC-Berechnungsroutine erfolgen, da Byte 0 Bestandteil des CRC-berechneten PDU-Bereichs ist.</li>\n</ul>"}], "trans": [{"from": "FIG-727ac805c5002da2", "to": "FIG-9f955fed7a787bc3", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
